import hashlib,json,os,re,subprocess,sys
p=sys.argv[1] if len(sys.argv)>1 else "SELFHOSTING.md"
t=open(p,encoding="utf-8").read(); L=t.split("\n"); bad=[]
if not t.endswith("\n"): bad.append("no final newline")
if len(L)-1>90: bad.append("longer than 90 lines: %d"%(len(L)-1))
bad+=["trailing whitespace on line %d"%(i+1) for i,x in enumerate(L) if x!=x.rstrip()]
if re.search(r"/Users/|/home/|~/\.claude/plugins/cache/\w",t): bad.append("a machine path")
def slugs(text):
  out=set(); fence=False
  for x in text.split("\n"):
    if x.startswith("```"): fence=not fence
    m=None if fence else re.match(r"#+ (.*)",x)
    if m: out.add(re.sub(r"[^\w\- ]","",m.group(1).strip().lower()).replace(" ","-"))
  return out
for href in re.findall(r"\]\(([^)\s]+)\)",t):
  if re.match(r"[a-z]+:",href): continue
  f,_,a=href.partition("#"); f=f or p
  if not os.path.exists(f): bad.append("link target missing: "+href); continue
  if a and a not in slugs(open(f,encoding="utf-8").read()): bad.append("anchor missing: "+href); continue
  head=subprocess.run(["git","show","HEAD:"+f],capture_output=True,text=True)
  if a and head.returncode==0 and a not in slugs(head.stdout): bad.append("anchor not in the committed "+f+": "+href)
